import type { Preview } from '@storybook/react-vite';
import { StrictMode, useLayoutEffect, useRef } from 'react';
import type { ReactNode } from 'react';
import { initialize, mswLoader } from 'msw-storybook-addon';
import appStyles from '../src/index.css?inline';
import heartAnimationStyles from '../src/assets/heartAnimation.css?inline';
import articleStyles from '../src/styles/Article.css?inline';
import { LikedArticlesProvider } from '../src/contexts/LikedArticlesContext';
import { mswHandlers } from './msw-handlers';

initialize({
  onUnhandledRequest: 'bypass',
});

const preview: Preview = {
  decorators: [
    (Story) => (
      <PreviewProviders>
            <Story />
      </PreviewProviders>
    ),
  ],
  loaders: [mswLoader],
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    a11y: {
      test: 'todo',
    },
    msw: {
      handlers: mswHandlers,
    },
  },
  async beforeEach() {
    localStorage.setItem('lang', 'en');
    localStorage.setItem('likedArticles', '[]');
  },
};

export default preview;

function PreviewProviders({ children }: { children: ReactNode }) {
  const rootRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const ownerDocument = rootRef.current?.ownerDocument;

    if (ownerDocument) {
      ensurePreviewStyles(ownerDocument);
    }
  }, []);

  return (
    <div ref={rootRef} style={{ display: 'contents' }}>
      <StrictMode>
        <LikedArticlesProvider>{children}</LikedArticlesProvider>
      </StrictMode>
    </div>
  );
}

function ensurePreviewStyles(ownerDocument: Document) {
  if (ownerDocument.getElementById('wikitok-preview-styles')) {
    return;
  }

  const style = ownerDocument.createElement('style');
  style.id = 'wikitok-preview-styles';
  style.textContent = [appStyles, heartAnimationStyles, articleStyles].join('\n');
  ownerDocument.head.append(style);
}

